    int time = 0;

    void dfs(int u, int parent) {
        disc[u] = low[u] = time++;
        for (int v : adj[u]) {
            if (v == parent) continue;               // not straight back along the same edge
            if (disc[v] == -1) {
                dfs(v, u);
                low[u] = min(low[u], low[v]);
                if (low[v] > disc[u]) bridges.push_back({u, v});   // v's subtree can't climb above it
            } else {
                low[u] = min(low[u], disc[v]);       // a back edge to an earlier vertex
            }
        }
    }

